<?php
require __DIR__.'/app/bootstrap.php';
$page=max(1,(int)(value('page',$_GET) ?: 1));$per=12;
$stats=one("SELECT COUNT(*) total,AVG(r.rating) average,COUNT(DISTINCT r.product_id) products_reviewed FROM reviews r JOIN products p ON p.id=r.product_id WHERE p.deleted_at IS NULL");
$total=(int)($stats['total'] ?? 0);$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;
$reviews=query("SELECT r.id,r.rating,r.comment,r.updated_at,u.name customer_name,p.id product_id,p.name product_name,p.image_path,p.category_id,c.name category_name FROM reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id JOIN categories c ON c.id=p.category_id WHERE p.deleted_at IS NULL ORDER BY r.updated_at DESC,r.id DESC LIMIT $per OFFSET $offset")->fetchAll();
page_header('Reviews');
?>
<section class="reviews-page"><p class="eyebrow">WHAT OUR CUSTOMERS SAY</p><h1>Customer reviews</h1><p>Feedback here comes from account customers after the website records a completed purchase of that product.</p>
<div class="review-stats" aria-label="Review summary"><article><strong><?= $total ?></strong><span>Total reviews</span></article><article><strong><?= $total?number_format((float)$stats['average'],1).' / 5':'—' ?></strong><span>Average rating</span></article><article><strong><?= (int)$stats['products_reviewed'] ?></strong><span>Products reviewed</span></article></div>
<?php if(!$reviews): ?><div class="form-card narrow review-empty-page"><h2>No reviews yet</h2><p>Verified reviews will appear here after customers complete purchases and review their sweets.</p><a class="button" href="products.php">Browse sweets</a></div><?php else: ?><div class="all-reviews-grid"><?php foreach($reviews as $review): ?><article class="all-review-card"><a class="review-product-thumb" href="product-details.php?id=<?= (int)$review['product_id'] ?>#reviews"><img src="<?= e(url(product_picture($review))) ?>" alt="<?= e($review['product_name']) ?>" loading="lazy"></a><div class="all-review-content"><span class="category"><?= e($review['category_name']) ?></span><h2><a href="product-details.php?id=<?= (int)$review['product_id'] ?>#reviews"><?= e($review['product_name']) ?></a></h2><div class="review-topline"><strong><?= e($review['customer_name']) ?></strong><span class="review-stars" aria-label="<?= (int)$review['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></span></div><p><?= nl2br(e($review['comment'])) ?></p><small><?= e(date('j M Y',strtotime($review['updated_at']))) ?> · Verified completed purchase</small><div class="review-card-action"><a class="text-link" href="product-details.php?id=<?= (int)$review['product_id'] ?>#write-review">View product / leave a review</a></div></div></article><?php endforeach ?></div><?php endif ?>
<?php if($pages>1): ?><nav class="pagination" aria-label="Review pages"><?php for($i=1;$i<=$pages;$i++): ?><a <?= $i===$page?'aria-current="page"':'' ?> href="?page=<?= $i ?>"><?= $i ?></a><?php endfor ?></nav><?php endif ?>
</section><?php page_footer(); ?>
